// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.json;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import org.eclipse.rdf4j.common.annotation.Experimental;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;

/**
 * A compiled JSONPath expression supporting the commonly used subset: {@code $} (root, optional), {@code .name},
 * {@code ['name']} / {@code ["name"]}, {@code [index]} (negative indices count from the end), {@code [*]} / {@code .*}
 * (all members), {@code ..name} and {@code ..*} (recursive descent). Compiled paths are cached.
 */
@Experimental
public final class JsonPath {

	private static final int MAX_CACHED = 512;
	private static final ConcurrentHashMap<String, JsonPath> CACHE = new ConcurrentHashMap<>();

	private enum Kind {
		KEY,
		INDEX,
		WILDCARD,
		RECURSIVE_KEY,
		RECURSIVE_WILDCARD
	}

	private record Step(Kind kind, String key, int index) {
	}

	private final Step[] steps;
	private final boolean definite;

	private JsonPath(Step[] steps) {
		this.steps = steps;
		boolean def = true;
		for (Step step : steps) {
			if (step.kind != Kind.KEY && step.kind != Kind.INDEX) {
				def = false;
			}
		}
		this.definite = def;
	}

	public static JsonPath compile(String path) {
		JsonPath compiled = CACHE.get(path);
		if (compiled == null) {
			compiled = parse(path);
			if (CACHE.size() >= MAX_CACHED) {
				CACHE.clear();
			}
			CACHE.put(path, compiled);
		}
		return compiled;
	}

	/** True when every step selects a single member, so the path addresses at most one location. */
	public boolean isDefinite() {
		return definite;
	}

	public int length() {
		return steps.length;
	}

	private static JsonPath parse(String path) {
		String p = path.trim();
		int pos = 0;
		if (p.startsWith("$")) {
			pos = 1;
		} else if (!p.isEmpty() && p.charAt(0) != '.' && p.charAt(0) != '[') {
			p = "." + p;
		}
		List<Step> steps = new ArrayList<>();
		while (pos < p.length()) {
			char c = p.charAt(pos);
			if (c == '.') {
				pos++;
				boolean recursive = false;
				if (pos < p.length() && p.charAt(pos) == '.') {
					recursive = true;
					pos++;
				}
				if (pos < p.length() && p.charAt(pos) == '[') {
					if (!recursive) {
						throw invalid(path);
					}
					// "..[*]" / "..['x']" handled by the bracket branch with recursive flag
					int end = p.indexOf(']', pos);
					if (end < 0) {
						throw invalid(path);
					}
					steps.add(bracket(p.substring(pos + 1, end).trim(), recursive, path));
					pos = end + 1;
					continue;
				}
				int start = pos;
				while (pos < p.length() && p.charAt(pos) != '.' && p.charAt(pos) != '[') {
					pos++;
				}
				String name = p.substring(start, pos);
				if (name.isEmpty()) {
					throw invalid(path);
				}
				if (name.equals("*")) {
					steps.add(new Step(recursive ? Kind.RECURSIVE_WILDCARD : Kind.WILDCARD, null, 0));
				} else {
					steps.add(new Step(recursive ? Kind.RECURSIVE_KEY : Kind.KEY, name, 0));
				}
			} else if (c == '[') {
				int end = p.indexOf(']', pos);
				if (end < 0) {
					throw invalid(path);
				}
				steps.add(bracket(p.substring(pos + 1, end).trim(), false, path));
				pos = end + 1;
			} else {
				throw invalid(path);
			}
		}
		return new JsonPath(steps.toArray(new Step[0]));
	}

	private static Step bracket(String content, boolean recursive, String path) {
		if (content.equals("*")) {
			return new Step(recursive ? Kind.RECURSIVE_WILDCARD : Kind.WILDCARD, null, 0);
		}
		if (content.length() >= 2 && (content.charAt(0) == '\'' || content.charAt(0) == '"')
				&& content.charAt(content.length() - 1) == content.charAt(0)) {
			return new Step(recursive ? Kind.RECURSIVE_KEY : Kind.KEY, content.substring(1, content.length() - 1), 0);
		}
		if (recursive) {
			throw invalid(path);
		}
		try {
			return new Step(Kind.INDEX, null, Integer.parseInt(content));
		} catch (NumberFormatException e) {
			throw invalid(path);
		}
	}

	private static ValueExprEvaluationException invalid(String path) {
		return new ValueExprEvaluationException("Invalid JSON path: " + path);
	}

	/** All values selected by this path, in document order. */
	@SuppressWarnings("unchecked")
	public List<Object> select(Object root) {
		List<Object> current = new ArrayList<>(1);
		current.add(root);
		for (Step step : steps) {
			List<Object> next = new ArrayList<>();
			for (Object node : current) {
				switch (step.kind) {
				case KEY:
					if (node instanceof Map<?, ?> map && map.containsKey(step.key)) {
						next.add(map.get(step.key));
					}
					break;
				case INDEX:
					if (node instanceof List<?> list) {
						int index = step.index < 0 ? list.size() + step.index : step.index;
						if (index >= 0 && index < list.size()) {
							next.add(list.get(index));
						}
					}
					break;
				case WILDCARD:
					children(node, next);
					break;
				case RECURSIVE_KEY:
					descend(node, step.key, next);
					break;
				default:
					descendAll(node, next);
				}
			}
			current = next;
			if (current.isEmpty()) {
				break;
			}
		}
		return current;
	}

	@SuppressWarnings("unchecked")
	private static void children(Object node, List<Object> out) {
		if (node instanceof Map<?, ?> map) {
			out.addAll(((Map<String, Object>) map).values());
		} else if (node instanceof List<?> list) {
			out.addAll((List<Object>) list);
		}
	}

	@SuppressWarnings("unchecked")
	private static void descend(Object node, String key, List<Object> out) {
		if (node instanceof Map<?, ?> map) {
			Map<String, Object> object = (Map<String, Object>) map;
			if (object.containsKey(key)) {
				out.add(object.get(key));
			}
			for (Object child : object.values()) {
				descend(child, key, out);
			}
		} else if (node instanceof List<?> list) {
			for (Object child : list) {
				descend(child, key, out);
			}
		}
	}

	@SuppressWarnings("unchecked")
	private static void descendAll(Object node, List<Object> out) {
		if (node instanceof Map<?, ?> map) {
			for (Object child : ((Map<String, Object>) map).values()) {
				out.add(child);
				descendAll(child, out);
			}
		} else if (node instanceof List<?> list) {
			for (Object child : list) {
				out.add(child);
				descendAll(child, out);
			}
		}
	}

	/**
	 * Sets the value at this (definite) path inside a mutable copy of {@code root}, creating missing objects along the
	 * way; out-of-range array indices append (positive) or prepend (negative).
	 */
	@SuppressWarnings("unchecked")
	public Object set(Object root, Object value) {
		if (!definite) {
			throw new ValueExprEvaluationException("JSON path for set operations must not contain wildcards");
		}
		if (steps.length == 0) {
			return value;
		}
		Object copy = JsonSupport.deepCopy(root);
		Object node = copy;
		for (int i = 0; i < steps.length; i++) {
			Step step = steps[i];
			boolean last = i == steps.length - 1;
			if (step.kind == Kind.KEY) {
				if (!(node instanceof Map)) {
					throw new ValueExprEvaluationException("JSON path step ." + step.key + " applied to a non-object");
				}
				Map<String, Object> object = (Map<String, Object>) node;
				if (last) {
					object.put(step.key, value);
				} else {
					Object child = object.get(step.key);
					if (!(child instanceof Map) && !(child instanceof List)) {
						child = steps[i + 1].kind == Kind.INDEX ? new ArrayList<>() : new java.util.LinkedHashMap<>();
						object.put(step.key, child);
					}
					node = child;
				}
			} else {
				if (!(node instanceof List)) {
					throw new ValueExprEvaluationException(
							"JSON path step [" + step.index + "] applied to a non-array");
				}
				List<Object> list = (List<Object>) node;
				int index = step.index < 0 ? list.size() + step.index : step.index;
				if (last) {
					if (index >= list.size()) {
						list.add(value);
					} else if (index < 0) {
						list.add(0, value);
					} else {
						list.set(index, value);
					}
				} else {
					if (index < 0 || index >= list.size()) {
						throw new ValueExprEvaluationException("JSON path index out of range: " + step.index);
					}
					Object child = list.get(index);
					if (!(child instanceof Map) && !(child instanceof List)) {
						child = steps[i + 1].kind == Kind.INDEX ? new ArrayList<>() : new java.util.LinkedHashMap<>();
						list.set(index, child);
					}
					node = child;
				}
			}
		}
		return copy;
	}
}
